namespace EtherGizmos.Common.Services;

internal class PfxSplitRawCertificateLoaderTests
{
    [Test]
    public async Task LoadCertificateAsync_WhenCalled_ShouldReturnCertificate()
    {
        //Arrange
        var factory = new PfxSplitRawCertificateLoader();

        //Act
        var certificate = await factory.LoadAsync(new()
        {
            PublicKeyBase64 = "",
            PrivateKeyBase64 = "",
        });

        //Assert
        Assert.That(certificate, Is.Not.Null);
    }
}
